    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String pattern = scanner.next();
        int length = pattern.length();

        if (length < 2) {
            System.out.println((pattern.equals("0") || pattern.equals("_") || pattern.equals("X")) ? 1 : 0);
            return;
        }

        if (length == 2) {
            int totalOptions = 0;
            for (int val = 10; val <= 95; val += 5) {
                if (val % 25 != 0) continue;
                String valStr = Integer.toString(val);
                char firstChar = pattern.charAt(0);
                char secondChar = pattern.charAt(1);
                if (Character.isDigit(firstChar)) {
                    if (Character.isDigit(secondChar)) {
                        if (pattern.equals(valStr)) totalOptions++;
                    } else {
                        if (firstChar == valStr.charAt(0)) totalOptions++;
                    }
                } else if (firstChar == '_') {
                    if (Character.isDigit(secondChar)) {
                        if (secondChar == valStr.charAt(1)) totalOptions++;
                    } else {
                        totalOptions++;
                    }
                } else {
                    if (Character.isDigit(secondChar)) {
                        if (secondChar == valStr.charAt(1)) totalOptions++;
                    } else if (secondChar == '_') {
                        totalOptions++;
                    }
                }
            }
            System.out.println(totalOptions);
            return;
        }

        int startNumber = (int) Math.pow(10, length - 1);
        int endNumber = (int) Math.pow(10, length);
        int countMatches = 0;

        for (int num = startNumber; num < endNumber; num += 25) {
            String numStr = Integer.toString(num);
            boolean matchesPattern = true;
            Set<Character> differingChars = new HashSet<>();
            for (int j = 0; j < length; j++) {
                char patternChar = pattern.charAt(j);
                char digitChar = numStr.charAt(j);
                if (patternChar == '_') continue;
                if (patternChar == 'X') {
                    differingChars.add(digitChar);
                } else if (patternChar != digitChar) {
                    matchesPattern = false;
                    break;
                }
            }
            if (matchesPattern && differingChars.size() < 2) countMatches++;
        }
        System.out.println(countMatches);
        scanner.close();
    }
}
